INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65546054', 65546054, 'analyze_legacy', 'Kementerian Perhubungan', 'central', 'BANDAR UDARA MOZES KILANGIN TIMIKA', 'POLIKLINIK/OBAT-OBATAN', 'Barang', 'Pengadaan Langsung', 'Papua Tengah, Mimika (Kab.)', 68100000, 'April 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', '1. Belanja Penambah Daya Tahan Tubuh;', 'Pekerjaan pengadaan suplemen penambah daya tahan tubuh merupakan kegiatan penyediaan produk kesehatan berupa vitamin dan/atau suplemen untuk mendukung peningkatan imunitas dan menjaga kebugaran personel dalam menunjang kelancaran operasional bandar udara. Ruang lingkup pekerjaan meliputi pengadaan suplemen yang mengandung vitamin C, vitamin D, zinc, multivitamin, atau kombinasi nutrisi lain yang berfungsi meningkatkan sistem imun, dengan ketentuan seluruh produk memiliki izin edar resmi dari BPOM, dikemas dalam kemasan asli dan tersegel, memiliki masa kedaluwarsa minimal 18–24 bulan sejak tanggal penerimaan, serta disertai dokumen keaslian dan faktur pembelian. Penyedia wajib menjamin mutu, keamanan, dan kualitas produk sesuai standar yang berlaku, serta mendistribusikan sesuai jumlah dan spesifikasi yang telah ditetapkan, sehingga kebutuhan peningkatan daya tahan tubuh personel dapat terpenuhi secara optimal dan sesuai ketentuan peraturan perundang-undangan di bidang kesehatan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2210718);
