INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65549697', 65549697, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Individu Ekonomi Rantai Nilai Dan Hilirisasi Industri Koordinasi Strategis Pengembangan Konektivitas Wilayah Untuk Peningkatan Nilai Tambah Wilayah Pembangunan Indonesia Barat', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 113000000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', '1. Analisis Penyusunan Rancangan Pengembangan Konektivitas Antarwilayah dan Rancangan Hilirisasi Industri dalam Penguatan Rantai Nilai Global Ruang lingkup pekerjaan ini mencakup pelaksanaan analisis sebagai dasar penyusunan Rancangan Pengembangan Konektivitas Antarwilayah serta Rancangan Hilirisasi Industri dalam Penguatan Rantai Nilai Global di Koridor Industri dan Logistik Jawa Bagian Barat, yang bertujuan mendukung keterpaduan pengembangan wilayah, peningkatan efisiensi logistik, dan penguatan peran wilayah dalam sistem ekonomi regional, nasional, dan global, serta menghasilkan arah kebijakan dan rekomendasi yang selaras dengan kebijakan nasional dan kebutuhan pembangunan daerah.', '1. Memiliki Pendidikan minimal S1 atau Sarjana dalam bidang Ekonomi dibuktikan dengan Ijazah dan/atau Surat Keterangan Lulus terkait; 2. Memiliki pengalaman kerja minimal 3 (tiga) tahun di bidang Ekonomi dibuktikan dengan dokumen CV dan/atau Portofolio; 3. Diutamakan pernah terlibat dalam pekerjaan sejenis seperti kesekretariatan badan/tim koordinasi strategis pada pembangunan kewilayahan; 4. Memiliki pengalaman dalam pekerjaan pengelolaan kawasan metropolitan/aglomerasi dan pernah menyusun kebijakan terkait pengelolaan kawasan metropolitan/aglomerasi; 5. Menguasai Bahasa Inggris dan Bahasa Indonesia dengan baik, dibuktikan dengan pengalaman menyusun laporan dalam Bahasa Inggris dan Bahasa Indonesia;', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2213397);
