INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65549174', 65549174, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultansi Individual: Penyusunan Kajian Desain Kelembagaan Dan Tata Kelola Standar Pelayanan Minimal Kegiatan Evaluasi Kebijakan Penerapan Standar Pelayanan Minimal (SPM) Di Daerah Direktorat Pemerintahan, Keuangan Daerah Dan Transfer Ke Daerah', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 132000000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', '1. Merumuskan draft konsep dan latar belakang substantif, tinjauan pustaka, metode yang akan digunakan baik metode pengumpulan data maupun metode analisis kegiatan peninjauan ulang kinerja penerapan Standar Pelayanan Minimal (SPM) di Daerah dalam aspek kelembagaan dan tata kelola penerapan SPM; 2. Melakukan inventarisasi dan identifikasi data, informasi, serta penyusunan draft konsep pelaporan penerapan SPM dalam aspek kelembagaan dan tata kelola penerapan SPM secara berkala; 3. Menyusun dan mempersiapkan draft konsep instrumen Forum Group Discussion (FGD) / indepth interview di tingkat Pusat mengenai penerapan SPM dan bagaimana kelembagaan dan tata kelolanya dengan melibatkan Kementerian/Lembaga pengampu urusan SPM serta mitra pembangunan;', '1. Merupakan Tenaga Ahli dalam negeri (Dibuktikan dengan identitas kewarganegaraan Indonesia seperti Kartu Tanda Penduduk); 2. Memiliki NPWP dan status valid Konfirmasi Status Wajib Pajak (KSWP); 3. Memiliki pendidikan minimal Strata Satu (S1) di bidang Ilmu Pemerintahan/Administrasi Negara/Administrasi Publik, yang dibuktikan dengan ijazah; 4. Memiliki pengalaman dalam bidang perencanaan atau evaluasi mengenai isu kebijakan desentralisasi dan otonomi daerah terutama pada bidang SPM minimal 2 (dua) tahun dalam kurun waktu 4 (empat) tahun terakhir yang dibuktikan dengan surat kontrak/referensi; 5. Memiliki pengalaman paling kurang 1 (satu) pekerjaan dalam kurun waktu 4 (empat) tahun terakhir baik di lingkungan pemerintah maupun swasta, termasuk pengalaman sub kontrak; 6. Memiliki pengalaman pekerjaan sejenis (jenis pekerjaan, kompleksitas pekerjaan, metodologi teknologi, atau karakteristik lainnya yang bisa menggambarkan kesamaan;Memiliki pengalaman pekerjaan dengan nilai pekerjaan sejenis tertinggi dalam kurun waktu 10 (sepuluh) tahun terakhir paling kurang sama dengan 50% nilai total HPS; 7. Memiliki kemampuan untuk melakukan pemodelan kebijakan dibuktikan dengan sertifikat seperti (Public Policy Modeling & Evaluation /System Dynamics/GIS & Spatial Modelling).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2213570);
