INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65550765', 65550765, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Individu Penyusunan Kajian Model Desentralisasi Pembangunan Nasional Di Tingkat Desa Kegiatan Koordinasi Strategis Peningkatan Kemandirian Perdesaan Yang Berkelanjutan Direktorat Perdesaan, Daerah Afirmasi, Dan Transmigrasi', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 213712000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '1', '1. Melakukan analisis terhadap regulasi dan kebijakan terkait yang mempengaruhi pelaksanaan desentralisasi pembangunan nasional pada level desa, termasuk kebijakan direktif presiden yang menyasar desa 2. Melakukan inventarisasi program Kementerian/Lembaga yang berjalan di desa serta identifikasi potensi konsolidasi program, terutama kegiatan yang bersumber dari Pinjaman Hibah dan Luar Negeri 3. Menyusun model desentralisasi pembangunan desa yang mengatur pembagian kewenangan, alur proses bisnis perencanaan, integrasi pendanaan, dan skema kelembagaan 4. Menyusun rekomendasi kebijakan untuk penguatan tata kelola desentralisasi desa 5. Melaksanakan alih pengetahuan (transfer of knowledge) atas hasil pekerjaan untuk memastikan keberlanjutan hasil pekerjaan.', '1. Pendidikan minimal S-2, berasal dari institusi berakreditasi baik dalam negeri maupun luar negeri pada bidang Administrasi Kebijakan Publik/Administrasi Kebijakan Bisnis, atau bidang relevan lainnya 2. Pengalaman minimal 20 (dua puluh) tahun dalam perencanaan pembangunan nasional dan daerah, desentralisasi, otonomi daerah, tata kelola pemerintahan, dan pembangunan desa 3. Pengalaman bekerja di Kementerian/Lembaga, khususnya dalam perencanaan pembangunan, koordinasi kebijakan nasional, atau sektor terkait (diutamakan memiliki pengalaman strategis di Bappenas atau unit perencanaan setara). 4. Pengalaman sebagai tenaga ahli/penanggung jawab proyek PHLN (grant/loan) atau kerja sama internasional), khususnya pada proyek pembangunan desa atau kelembagaan daerah. 5. Memiliki pengalaman sebagai narasumber/pembicara pada forum nasional terkait desentralisasi, tata kelola pemerintahan, penguatan desa, atau perencanaan pembangunan. 6. Memiliki pemahaman mendalam tentang siklus perencanaan–penganggaran nasional (RPJP/RPJMN/RKP), transfer ke daerah, dan hubungan kewenangan pusat–daerah–desa.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2214552);
