INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65549025', 65549025, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultansi Individual: Pengkajian Kinerja Penataan Desentralisasi Dan Otonomi Daerah Berbasis Manajemen Risiko  Kegiatan Pemantauan (Monitoring) RKP 2026 Dan Evaluasi RKP 2025 Lingkup Pemerintahan, Keuangan Daerah, Dan Transfer Ke Daerah Direktorat Pemerintahan, Keuangan Daerah', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 138000000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', '1. Menyusun desain tinjauan awal desain kerangka kerja, lini masa pengerjaan, metode, mekanisme pelaksanaan, serta usulan tematik monitoring tahun berjalan. 2. Melakukan inventarisasi isu potensial dan identifikasi awal pemetaan risiko dalam Penataan Desentralisasi dan Otonomi Daerah 3. Melaksanakan analisis permasalahan dalam pelaksanaan peninjauan kinerja Penataan Desentralisasi dan Otonomi Daerah di daerah 4. Melaksanakan perumusan tematik dan lokasi uji petik daerah dalam peninjauan kinerja Penataan Desentralisasi dan Otonomi Daerah 5. Menyusun rekomendasi mitigasi risiko pelaksanaan peninjauan kinerja Penataan Desentralisasi dan Otonomi Daerah 6. Melaksanakan koordinasi teknis lintas bidang dalam penyusunan laporan akhir kajian penataan desentralisasi dan otonomi daerah berbasis manajemen risiko; dan 7. Menyusun laporan akhir kajian penataan desentralisasi dan otonomi daerah berbasis manajemen risiko.', '1. Merupakan Tenaga Ahli dalam negeri yang dibuktikan dengan identitas kewarganegaraan Indonesia seperti Kartu Tanda Penduduk; 2. Memiliki NPWP dan memiliki status valid Konfirmasi Status Wajib Pajak (KSWP); 3. Memiliki pendidikan minimal Strata Satu (S1) di bidang Perencanaan Wilayah dan Kota/Statistik/Data Sains yang dibuktikan dengan ijazah; 4. Memiliki pengalaman paling kurang 1 (satu) pekerjaan dalam kurun waktu 4 (empat) tahun terakhir baik di lingkungan pemerintah maupun swasta, termasuk pengalaman sub kontrak; 5. Memiliki pengalaman minimal 1 (satu) tahun dalam kurun waktu 2 (dua) tahun terakhir pekerjaan yang berkaitan dengan penyusunan laporan pemantauan atau evaluasi di tingkat nasional atau daerah pada lingkup isu pemerintahan, pembangunan daerah, kebijakan desentralisasi dan otonomi daerah, atau kerja sama daerah yang dibuktikan dengan laporan pekerjaan/referensi yang pernah dilakukan; 6. Memiliki pengalaman pekerjaan sejenis (jenis pekerjaan, kompleksitas pekerjaan, metodologi teknologi, atau karakteristik lainnya yang bisa menggambarkan kesamaan;', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2214709);
