INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65588736', 65588736, 'analyze_legacy', 'Kementerian Imigrasi dan Pemasyarakatan', 'central', 'INSPEKTORAT JENDERAL', 'Pengadaan Biaya Pengisian Listrik Kendaraan Operasional Listrik Sewa Untuk Kegiatan Kendaraan Dinas Operasional Kantor Pada Inspektorat Jenderal Kementerian Imigrasi dan Pemasyarakatan Tahun Anggaran 2026', 'Jasa Lainnya', 'Dikecualikan', 'DKI Jakarta, Jakarta Selatan (Kota)', 52300000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '5.0 UT', 'Pengadaan biaya pengisian listrik untuk 5 (lima) unit kendaraan operasional listrik sewa yang digunakan dalam kegiatan kendaraan dinas operasional kantor pada Inspektorat Jenderal Kementerian Imigrasi dan Pemasyarakatan selama Tahun Anggaran 2026 dengan jangka waktu pelaksanaan 1 (satu) tahun. Pengadaan ini bertujuan untuk menjamin ketersediaan energi listrik guna mendukung kelancaran mobilitas dan pelaksanaan tugas kedinasan, termasuk kegiatan pengawasan, koordinasi, monitoring, evaluasi, serta kegiatan operasional perkantoran lainnya. Ruang lingkup pekerjaan meliputi penyediaan dan pembayaran biaya pengisian daya listrik sesuai kebutuhan operasional kendaraan, pelaksanaan pengisian melalui fasilitas pengisian yang sah dan memenuhi standar keselamatan, pengelolaan administrasi dan mekanisme pembayaran sesuai ketentuan perbendaharaan yang berlaku, pencatatan serta rekapitulasi konsumsi energi dan biaya pengisian secara berkala, serta penyusunan laporan realisasi penggunaan anggaran sebagai bentuk pertanggungjawaban administratif selama 12 (dua belas) bulan pelaksanaan kegiatan.', 'Spesifikasi pekerjaan pengadaan biaya pengisian listrik kendaraan operasional listrik sewa ini meliputi penyediaan kebutuhan energi listrik untuk 5 (lima) unit kendaraan selama 12 (dua belas) bulan Tahun Anggaran 2026, dengan estimasi konsumsi daya disesuaikan dengan intensitas penggunaan operasional kantor. Pengisian daya dilaksanakan melalui fasilitas pengisian kendaraan listrik yang memenuhi standar teknis dan keselamatan ketenagalistrikan yang berlaku, dengan sistem arus bolak-balik (AC) dan/atau arus searah (DC) sesuai kompatibilitas kendaraan, serta dilengkapi alat ukur konsumsi energi (kWh meter) yang terkalibrasi. Setiap transaksi pengisian wajib terdokumentasi dalam bukti pembayaran yang sah dan memuat informasi minimal berupa tanggal pengisian, jumlah energi terpakai (kWh), tarif per kWh, dan total biaya. Pelaksanaan pembayaran dilakukan melalui mekanisme non-tunai atau metode lain sesuai ketentuan perbendaharaan negara. Selain itu, dilakukan pencatatan dan rekapitulasi penggunaan energi listrik per unit kendaraan secara periodik (bulanan), termasuk pengendalian terhadap batas pagu anggaran, serta penyusunan laporan realisasi penggunaan biaya pengisian listrik secara berkala dan tahunan sebagai bagian dari pertanggungjawaban administrasi kegiatan kendaraan dinas operasional kantor.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2215085);
