INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65549357', 65549357, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Individu Arsitektur Pengembangan Kawasan Dan Hilirisasi Industri Koordinasi Strategis Pengembangan Konektivitas Wilayah Untuk Peningkatan Nilai Tambah Wilayah Pembangunan Indonesia Barat', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 118500000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', '1. Analisis Penyusunan Rancangan Pengembangan Konektivitas Antarwilayah dan Rancangan Hilirisasi Industri dalam Penguatan Rantai Nilai Global Ruang lingkup pekerjaan ini mencakup pemberian dukungan teknis arsitektural dalam sebagai dasar penyusunan Rancangan Pengembangan Konektivitas Antarwilayah serta Rancangan Hilirisasi Industri dalam Penguatan Rantai Nilai Global di Koridor Industri dan Logistik Jawa Bagian Barat, melalui perumusan konsep desain kawasan, prinsip penataan lingkungan binaan, dan integrasi fungsi kawasan industri, logistik, serta pemberian masukan teknis, pemantauan, dan evaluasi. Dukungan ini ditujukan untuk memperkuat kualitas desain dan keterpaduan kawasan agar selaras dengan arah kebijakan nasional, kebutuhan daerah, dan prinsip keterpaduan lintas sektor serta lintas wilayah.', '1. Memiliki Pendidikan minimal S1 atau Sarjana dalam bidang Arsitektur/Teknik dibuktikan dengan Ijazah dan/atau Surat Keterangan Lulus terkait; 2. Memiliki pengalaman kerja minimal 4 (empat) tahun di bidang Arsitektur dibuktikan dengan dokumen CV dan/atau Portofolio; 3. Diutamakan pernah terlibat dalam pekerjaan sejenis seperti kesekretariatan badan/tim koordinasi strategis pada pembangunan kewilayahan; 4. Memiliki pengalaman dalam pekerjaan pengelolaan kawasan metropolitan/aglomerasi dan pernah menyusun kebijakan terkait pengelolaan kawasan metropolitan/aglomerasi; 5. Menguasai Bahasa Inggris dan Bahasa Indonesia dengan baik, dibuktikan dengan pengalaman menyusun laporan dalam Bahasa Inggris dan Bahasa Indonesia; 6. Menguasai program AutoCAD (2D), SketchUp (3D), Adobe Illustrator, Photoshop dan sejenis lainnya; 7. Memiliki pengalaman dan kemampuan menulis ilmiah dengan baik, dibuktikan dengan penulisan karya ilmiah;', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2215438);
