INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65550881', 65550881, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Individual Penyusunan Rekomendasi Kebijakan Pengembangan Ekonomi Berbasis Potensi Unggulan Wilayah Papua Kegiatan Koordinasi Strategis Terpadu Perencanaan Percepatan Pembangunan Papua Direktorat Pembangunan Indonesia Timur', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 181500000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', '1. Memperjelas dan menajamkan strategi pembangunan kewilayahan bidang ekonomi serta penguatannya di wilayah Papua (struktur dan pertumbuhan ekonomi daerah, pengembangan sektor unggulan, investasi dan perdagangan, ekonomi lokal, perindustrian dan perkoperasian, fasilitasi IKM dan UKM, infrastruktur pendukung, dan bidang lainnya yang relevan) melalui serangkaian pertemuan multisektor (internal pemerintah) dan workshop/seminar (melibatkan seluruh aktor pembangunan) baik di tingkat pusat maupun daerah. 2. Memberi dukungan analisis dalam proses penyusunan rekomendasi pengembangan ekonomi melalui kegiatan prioritas Kementerian/Lembaga dan Pemerintah Daerah bidang ekonomi (pengembangan ekosistem pertanian/perkebunan, perikanan, pariwisata dan ekonomi kreatif, industri, investasi, UMKM dan koperasi, perdagangan, dan sektor lainnya yang relevan) dan kondisi perlu yang mendukung Rencana Aksi Percepatan Pembangunan Papua (RAPPP) 2025-2029, dengan prinsip sinergi antarsumber pendanaan;', '1. Pendidikan minimal S2 yang berasal dari institutsi terakreditasi, baik dari dalam negeri maupun luar negeri pada bidang bidang Ekonomi/Administrasi Publik, yang dibuktikan dengan ijazah; 2. Nilai pekerjaan sejenis tertinggi dalam kurun waktu 10 (sepuluh) tahun terkahir paling kurang sama dengan 50% (lima puluh persen) nilai HPS/Pagu Anggaran; 3. Memiliki pengalaman paling kurang 1 (satu) pekerjaan dalam kurun waktu 4 (empat) tahun terakhir baik di lingkungan pemerintah maupun swasta, termasuk pengalaman subkontrak; 4. Memiliki pengalaman pekerjaan sejenis di bidang perencanaan, evaluasi kebijakan pemerintah, dan/atau pembangunan daerah dan pemberdayaan pemerintah daerah maupun masyarakat di bidang ekonomi pembangunan minimal 8 (delapan) tahun, dibuktikan dengan surat kontrak/referensi pekerjaan; 5. Diutamakan pernah bekerja di instansi pemerintahan, lembaga donor/mitra pembangunan, NGO, dan/atau CSO yang dibuktikan dengan surat kontrak/referensi pekerjaan; 6. Menguasai isu-isu terkait pembangunan yang ada di Wilayah Papua, khususnya isu di bidang ekonomi (pengembangan ekosistem pertanian/perkebunan, perikanan, pariwisata dan ekonomi kreatif, industri, investasi, UMKM dan koperasi, perdagangan, dan sektor lainnya yang relevan) dibuktikan dengan portofolio/hasil riset/tulisan/penyusunan kebijakan terkait, terutama di Wilayah Papua; 7. Memiliki kemampuan analisis wilayah dan penyiapan laporan/bahan presentasi/dokumen analisis terkait persoalan di bidangnya dibuktikan dengan dokumen publikasi yang pernah disusun;', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2216870);
