INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65588869', 65588869, 'analyze_legacy', 'Kementerian Imigrasi dan Pemasyarakatan', 'central', 'INSPEKTORAT JENDERAL', 'Pengadaan BBBM Kendaraan Dinas Operasional Pinjaman Untuk Kegiatan Kendaraan Dinas Operasional Kantor Pada Inspektorat Jenderal Kementerian Imigrasi dan Pemasyarakatan Tahun Anggaran 2026', 'Jasa Lainnya', 'Dikecualikan', 'DKI Jakarta, Jakarta Selatan (Kota)', 90000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '6.0 UT', 'Pengadaan Bahan Bakar Minyak (BBM) untuk 6 (enam) unit kendaraan dinas operasional pinjaman yang digunakan dalam kegiatan kendaraan dinas operasional kantor pada Inspektorat Jenderal Kementerian Imigrasi dan Pemasyarakatan selama Tahun Anggaran 2026 dengan jangka waktu pelaksanaan 1 (satu) tahun. Pengadaan ini bertujuan untuk menjamin ketersediaan bahan bakar guna mendukung kelancaran mobilitas dan pelaksanaan tugas kedinasan, termasuk kegiatan pengawasan, koordinasi, monitoring, evaluasi, serta kegiatan operasional perkantoran lainnya. Ruang lingkup pekerjaan meliputi penyediaan dan pembayaran BBM sesuai kebutuhan operasional masing-masing kendaraan berdasarkan standar konsumsi dan jarak tempuh, pengisian BBM pada penyedia yang sah dan sesuai ketentuan peraturan perundang-undangan, pengelolaan mekanisme pembayaran secara non-tunai atau metode lain sesuai ketentuan perbendaharaan negara, pencatatan dan rekapitulasi penggunaan BBM per unit kendaraan secara berkala, serta penyusunan laporan realisasi penggunaan anggaran sebagai bentuk pertanggungjawaban administrasi dalam aplikasi SIRUP dan sistem pengelolaan keuangan yang berlaku.', 'Spesifikasi pekerjaan pengadaan Bahan Bakar Minyak (BBM) kendaraan dinas operasional pinjaman ini meliputi penyediaan kebutuhan BBM untuk 6 (enam) unit kendaraan selama 12 (dua belas) bulan Tahun Anggaran 2026, dengan jenis bahan bakar disesuaikan dengan spesifikasi teknis masing-masing kendaraan (misalnya bensin atau solar sesuai rasio kompresi dan sistem mesin kendaraan). Perkiraan volume BBM dihitung berdasarkan estimasi jarak tempuh dan standar konsumsi rata-rata kendaraan operasional, dengan pengendalian agar tidak melebihi pagu anggaran yang ditetapkan. Pengisian BBM dilakukan pada stasiun pengisian bahan bakar resmi yang memiliki izin operasional dan memenuhi standar keselamatan serta ketentuan distribusi BBM yang berlaku. Sistem pembayaran dilaksanakan secara non-tunai atau mekanisme lain yang sesuai dengan ketentuan perbendaharaan negara dan dilengkapi bukti transaksi yang sah, memuat sekurang-kurangnya tanggal pengisian, jenis BBM, jumlah liter, harga per liter, serta total biaya. Selain itu, dilakukan pencatatan dan rekapitulasi penggunaan BBM per unit kendaraan secara periodik (bulanan), termasuk pengendalian terhadap batas konsumsi dan pagu anggaran, serta penyusunan laporan realisasi penggunaan BBM sebagai bagian dari pertanggungjawaban administrasi kegiatan kendaraan dinas operasional kantor.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2217061);
