INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65548843', 65548843, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultasi Individual Penyusunan Kajian Model Dan Analisis Kapasitas Pendapatan, Belanja, Dan Pembiayaan Daerah Kegiatan Prakarsa Strategis Optimalisasi Sumber-Sumber Pendapatan Daerah Dan Peningkatan Kualitas Belanja Direktorat Pemerintahan, Keuangan Daerah, Dan Transfer Ke Daerah', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 144000000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', '1. Menyusun kerangka kerja kegiatan, termasuk instrumen, jadwal, dan mekanisme pelaksanaan; 2. Melakukan analisis identifikasi determinan sumber-sumber PAD dan jenis-jenis belanja daerah yang dapat mendorong pertumbuhan ekonomi di daerah; 3. Menyusun model yang dapat menggambarkan bukti adanya keterkaitan determinan PAD, belanja daerah, dan pembiayaan terhadap pertumbuhan ekonomi di daerah; 4. Menyusun model pemetaan pembiayaan daerah berdasarkan kapasitas keuangan daerah; 5. Menyusun rancangan rekomendasi strategi peningkatan pertumbuhan ekonomi di daerah berdasarkan determinan PAD, belanja, dan pembiayaan daerah dalam jangka pendek, menengah dan jangka panjang; 6. Membantu tim dalam berkoordinasi di internal Kementerian PPN/Bappenas maupun dengan K/L terkait; serta 7. Menyusun laporan akhir model dan analisis kapasitas pendapatan, belanja, dan pembiayaan daerah.', '1. Merupakan Tenaga Ahli dalam negeri (Dibuktikan dengan identitas kewarganegaraan Indonesia seperti Kartu Tanda Penduduk); 2. Memiliki NPWP dan status valid Konfirmasi Status Wajib Pajak (KSWP); 3. Memiliki pendidikan minimal Strata Satu (S2) di bidang Penyusunan Model dan Analisis Kapasitas Pendapatan, Belanja, dan Pembiayaan Daerah/Studi Pembangunan; 4. Memiliki pengalaman paling kurang 5 (lima) tahun dalam kurun waktu 3 (tiga) tahun terakhir baik di lingkungan pemerintahan maupun swasta, termasuk pengalaman subkontrak; 5. Memiliki pekerjaan sejenis (jenis pekerjaan, kompleksitas pekerjaan, metodologi, teknologi atau karakteristik lainnya yang bisa menggambarkan kesamaan), yaitu dalam bidang koordinasi strategis keuangan daerah yang dibuktikan dengan surat kontrak/referensi pekerjaan yang pernah dilakukan; 6. Memiliki sertifikasi yang berkaitan dalam pengelolaan keuangan daerah (pendapatan, belanja atau pembiyaan) yang dibuktikan melalui sertifikat. 7. Menguasai implementasi dari UU No. 1 Tahun 2022 tentang Hubungan Keuangan antara Pemerintah Pusat dan Pemerintahan Daerah yang dibuktikan melalui sertifikat /laporan/kajian/presentasi formal.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2217531);
