INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65588608', 65588608, 'analyze_legacy', 'Kementerian Imigrasi dan Pemasyarakatan', 'central', 'INSPEKTORAT JENDERAL', 'Pengadaan Biaya Pengisian Listrik Kendaraan Fungsional Listrik Sewa Untuk Kegiatan Kendaraan Dinas Operasional Kantor Pada Inspektorat Jenderal Kementerian Imigrasi dan Pemasyarakatan Tahun Anggaran 2026', 'Jasa Lainnya', 'Dikecualikan', 'DKI Jakarta, Jakarta Selatan (Kota)', 41840000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '4.0 UT', 'Pengadaan biaya pengisian listrik (charging) untuk 4 (empat) unit kendaraan fungsional listrik sewa yang digunakan dalam kegiatan kendaraan dinas operasional pada Inspektorat Jenderal Kementerian Imigrasi dan Pemasyarakatan Tahun Anggaran 2026 selama jangka waktu 1 (satu) tahun anggaran. Pengadaan ini bertujuan untuk mendukung kelancaran mobilitas dan pelaksanaan tugas kedinasan, termasuk kegiatan pengawasan, monitoring, evaluasi, serta kegiatan operasional lainnya. Ruang lingkup pekerjaan meliputi penyediaan dan pembayaran biaya pengisian daya listrik melalui fasilitas Stasiun Pengisian Kendaraan Listrik Umum (SPKLU) atau sarana pengisian lainnya yang sah, pengelolaan mekanisme pembayaran sesuai ketentuan yang berlaku, pencatatan dan rekapitulasi penggunaan biaya pengisian listrik secara berkala, serta penyusunan laporan realisasi anggaran sebagai bentuk pertanggungjawaban administrasi selama Tahun Anggaran 2026.', 'Spesifikasi pekerjaan ini meliputi penyediaan biaya pengisian daya listrik untuk 4 (empat) unit kendaraan fungsional listrik sewa selama 12 (dua belas) bulan Tahun Anggaran 2026, dengan kapasitas dan jumlah pengisian disesuaikan dengan kebutuhan operasional kendaraan dinas. Pengisian daya dilakukan menggunakan sumber listrik standar yang sesuai dengan sistem pengisian kendaraan listrik, baik melalui fasilitas Stasiun Pengisian Kendaraan Listrik Umum (SPKLU) maupun fasilitas pengisian lainnya yang memenuhi standar keselamatan dan ketentuan yang berlaku, dengan tegangan dan konektor yang kompatibel dengan spesifikasi kendaraan. Setiap pelaksanaan pengisian daya harus dapat diukur berdasarkan konsumsi energi listrik (kWh) dan nilai biaya pengisian, serta didukung dengan bukti transaksi yang sah. Selain itu, dilakukan pencatatan dan rekapitulasi penggunaan energi listrik dan biaya pengisian per kendaraan secara berkala, serta penyusunan laporan realisasi penggunaan biaya pengisian listrik sebagai bagian dari pertanggungjawaban administrasi kegiatan kendaraan dinas operasional.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2218080);
