INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65550240', 65550240, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Individu Penyusunan Kajian Penguatan Kebutuhan Dan Insentif Fiskal Desa Kegiatan Prakarsa Strategis Inisiasi Pengembangan Rural Development Support Facility  Fund (RDSF) Direktorat Perdesaan, Daerah Afirmasi, Dan Transmigrasi', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 193500000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '1', '1. Memberikan dukungan teknis dalam melakukan tugas dan fungsi Direktorat PDAT sesuai bidang keahlian. 2. Menyusun pemetaan kebutuhan data, potensi desa, serta identifikasi sumber pendanaan alternatif, termasuk CSR, hibah, dan donor. 3. Menyusun penyusunan framework strategi pembangunan desa terpadu yang relevan dengan prioritas nasional dan prinsip kemandirian desa. 4. Menyusun pemetaan pemangku kepentingan (K/L, pemda, swasta, filantropi, lembaga donor) dan merancang mekanisme koordinasi serta alur kerja pendanaan alternatif.', '1. Pendidikan minimal S2 pada bidang urban management and development, perencanaan pembangunan, kebijakan publik, ekonomi pembangunan, atau bidang terkait. 2. Pengalaman minimal 10 tahun dalam perencanaan pembangunan, pembiayaan pembangunan, CSR, atau pengembangan program berbasis desa/daerah. 3. Memahami kebijakan nasional terkait desa (UU Desa, RPJMN, SDGs Desa, PODES, Indeks Desa). 4. Memiliki pengalaman dalam analisis pendanaan, perancangan model pembiayaan, dan kerjasama multipihak. 5. Mampu menyusun laporan, policy paper, dan presentasi secara efektif. 6. Mampu bekerja lintas sektor dan melakukan koordinasi dengan pemerintah, swasta, dan lembaga donor.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2218737);
